 1→package com.cowave.search.domain.index.policy
 2→
 3→import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.Product
 4→import com.cowave.search.domain.index.dto.ChangedData
 5→import com.cowave.search.domain.index.enums.Operation
 6→import com.cowave.shared.utils.logger
 7→
 8→object ProductMergeStrategy : MergeStrategy<Product> {
 9→    private val logger by logger()
10→
11→    override fun merge(documents: List<ChangedData<Product>>): List<ChangedData<Product>> =
12→        documents
13→            .groupBy { it.id } // 같은 문서로 그룹핑
14→            .map { (_, group) ->
15→                if (group.size == 1) {
16→                    group.first().apply {
17→                        when (op) {
18→                            Operation.CREATE -> {
19→                                shouldFetchCategory = true
20→                                shouldFetchBrand = true
21→                                shouldFetchManufacturer = true
22→                                shouldFetchMall = true
23→                            }
24→                            Operation.UPDATE -> {
25→                                shouldFetchCategory = beforeData?.categoryId != afterData?.categoryId
26→                                shouldFetchBrand = beforeData?.brandId != afterData?.brandId
27→                                shouldFetchManufacturer = beforeData?.manufacturerId != afterData?.manufacturerId
28→                                shouldFetchMall = beforeData?.mallId != afterData?.mallId
29→                            }
30→                            Operation.DELETE -> {
31→                                shouldFetchCategory = false
32→                                shouldFetchBrand = false
33→                                shouldFetchManufacturer = false
34→                                shouldFetchMall = false
35→                            }
36→                        }
37→                    }
38→                } else {
39→                    var isChangedCategory = false
40→                    var isChangedBrand = false
41→                    var isChangedManufacturer = false
42→                    var isChangedMall = false
43→
44→                    group
45→                        .sortedBy { it.offset } // offset 기준으로 정렬
46→                        .fold(null as ChangedData<Product>?) { acc, current ->
47→                            when (current.op) {
48→                                Operation.CREATE -> {
49→                                    isChangedCategory = true
50→                                    // Note. product의 brand, manufacturer 연동은 아직 되고 있지 않지만 미리 작업해둠
51→                                    isChangedBrand = true
52→                                    isChangedManufacturer = true
53→                                    isChangedMall = true
54→                                }
55→
56→                                Operation.UPDATE -> {
57→                                    // Note. update 메시지의 before가 null인 경우 존재
58→                                    // Note. 변경점이 있을 때만 diff 결과 true 유지
59→                                    if (current.beforeData != null && current.afterData != null) {
60→                                        if (current.beforeData.categoryId != current.afterData.categoryId) isChangedCategory = true
61→                                        if (current.beforeData.brandId != current.afterData.brandId) isChangedBrand = true
62→                                        if (current.beforeData.manufacturerId != current.afterData.manufacturerId) isChangedManufacturer = true
63→                                        if (current.beforeData.mallId != current.afterData.mallId) isChangedMall = true
64→                                    }
65→                                }
66→
67→                                Operation.DELETE -> {
68→                                    isChangedCategory = false
69→                                    isChangedBrand = false
70→                                    isChangedManufacturer = false
71→                                    isChangedMall = false
72→                                }
73→                            }
74→
75→                            merge(acc, current)
76→                                .also {
77→                                    if (it == null) {
78→                                        // Note. merge result가 null인 경우, acc는 not null이 보장됨
79→                                        logger.warn { "[ProductMergeStrategy] Unexpected operation. " + diffLog(acc!!, current) }
80→                                    }
81→                                }
82→                        }.apply {
83→                            this?.shouldFetchCategory = isChangedCategory
84→                            this?.shouldFetchBrand = isChangedBrand
85→                            this?.shouldFetchManufacturer = isChangedManufacturer
86→                            this?.shouldFetchMall = isChangedMall
87→                        }
88→                }
89→            }.filterNotNull()
90→}
